        );
        assert_eq!(
            get_filename_from_diff_header_line_file_path("b/src/pa rse.rs"),
            Some("pa rse.rs")
        );
        assert_eq!(
            get_filename_from_diff_header_line_file_path("src/pa rse.rs"),
            Some("pa rse.rs")
        );
        assert_eq!(
            get_filename_from_diff_header_line_file_path("wat hello.rs"),
